// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useRef } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
// ------------------------------------------------------------------
// FONTS
// ------------------------------------------------------------------
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// ------------------------------------------------------------------
// SCHEMA
// ------------------------------------------------------------------


export type RobotLoaderProps = Record<string, any>;

// ------------------------------------------------------------------
// COMPONENT
// ------------------------------------------------------------------
const RobotLoader: React.FC<RobotLoaderProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  primaryColor = "#FF6B35",
  secondaryColor = "#9CA3AF",
  ballColor = "#1F2937",
  leftLabel = "Final AI Review...",
  loaders = [
    "Building Environment...",
    "Learning about you...",
    "Generating Ramp Times...",
    "Configuring Quotas...",
    "Setting up Territories...",
  ],
  durationInSeconds = 8,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Safety for background transparency
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Scale factor to increase the overall size of the animation
  const containerScale = 1.75;

  // ------------------------------------------------------------------
  // ANIMATION DRIVERS
  // ------------------------------------------------------------------

  // 1. Entrance of the central structure (Line + Ball)
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 200, stiffness: 100 },
  });

  // 2. Continuous rotation of the ball
  const rotation = interpolate(frame, [0, 300], [0, 360]);

  // 3. Line Scale
  const lineScale = interpolate(entranceSpring, [0, 1], [0, 1]);

  // ------------------------------------------------------------------
  // HELPER: SPLIT TEXT (Last 2 words colored)
  // ------------------------------------------------------------------
  const renderColoredText = (text: string) => {
    const words = text.split(" ");
    if (words.length <= 1)
      return <span style={{ color: secondaryColor }}>{text}</span>;

    // Heuristic: Last 2 words are primary color, rest are secondary
    const splitIndex = Math.max(0, words.length - 2);
    const firstPart = words.slice(0, splitIndex).join(" ");
    const secondPart = words.slice(splitIndex).join(" ");

    return (
      <>
        {firstPart && (
          <span style={{ color: secondaryColor, marginRight: 10 }}>
            {firstPart}
          </span>
        )}
        <span style={{ color: primaryColor, fontWeight: 600 }}>
          {secondPart}
        </span>
      </>
    );
  };

  // ------------------------------------------------------------------
  // SCROLL LOGIC PRE-CALCULATION
  // ------------------------------------------------------------------
  const ITEM_HEIGHT = 60; // Spacing between items
  const CONTAINER_HEIGHT = 300;
  const CENTER_Y = CONTAINER_HEIGHT / 2;
  const START_Y_POS = CONTAINER_HEIGHT + 30; // Start with first item below view
  
  // Calculate total scroll needed to land the LAST item exactly in the center
  const lastItemIndex = Math.max(0, loaders.length - 1);
  const lastItemInitialY = START_Y_POS + (lastItemIndex * ITEM_HEIGHT);
  const totalDistanceToScroll = lastItemInitialY - CENTER_Y;

  const durationInFrames = durationInSeconds * fps;
  
  // Interpolate scroll offset so it clamps exactly when the last item hits the center
  const currentScrollOffset = interpolate(
    frame,
    [0, durationInFrames],
    [0, totalDistanceToScroll],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "Inter, sans-serif",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      {/* 
        Container Wrapper:
        Applies the scale transform to enlarge all elements proportionately.
        Flex layout is applied here to maintain structure inside the scaled coordinate system.
      */}
      <div
        style={{
          transform: `scale(${containerScale})`,
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          gap: width * 0.04,
        }}
      >
        {/* ------------------------------------------------------------------
            LEFT SECTION: Label + Sparkle
        ------------------------------------------------------------------ */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 16,
            opacity: entranceSpring,
            transform: `translateX(${interpolate(
              entranceSpring,
              [0, 1],
              [-20, 0]
            )}px)`,
          }}
        >
          {/* Sparkle Icon */}
          <svg
            width="32"
            height="32"
            viewBox="0 0 24 24"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M12 2L14.4 9.6L22 12L14.4 14.4L12 22L9.6 14.4L2 12L9.6 9.6L12 2Z"
              fill={secondaryColor}
              opacity={0.6}
            />
          </svg>

          {/* Wave Text Effect */}
          <div
            style={{
              fontSize: 32,
              color: secondaryColor,
              fontWeight: 500,
              whiteSpace: "pre", // Crucial to preserve spaces in split text
              display: "flex",
              flexDirection: "row",
            }}
          >
            {leftLabel.split("").map((char, i) => {
              // Create a sine wave traveling through the text
              // Frame * speed controls speed, i * offset controls wave tightness
              const wave = Math.sin(frame * 0.2 - i * 0.3);

              // Map sine range [-1, 1] to opacity range [0.3, 1]
              const opacity = interpolate(wave, [-1, 1], [0.3, 1]);

              return (
                <span key={i} style={{ opacity }}>
                  {char}
                </span>
              );
            })}
          </div>
        </div>

        {/* ------------------------------------------------------------------
            CENTER SECTION: Ball + Line + Arc
        ------------------------------------------------------------------ */}
        <div
          style={{
            position: "relative",
            width: 120,
            height: 300, // Tall enough for the line
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {/* Vertical Line */}
          <div
            style={{
              position: "absolute",
              width: 2,
              height: "100%",
              background: `linear-gradient(to bottom, transparent, ${primaryColor}40, transparent)`,
              transform: `scaleY(${lineScale})`,
              transformOrigin: "center",
            }}
          />

          {/* The Arc (Right side) */}
          <svg
            width="160"
            height="160"
            viewBox="0 0 160 160"
            style={{
              position: "absolute",
              left: "50%",
              top: "50%",
              transform: "translate(-50%, -50%)",
              overflow: "visible",
            }}
          >
            {/* Semicircle Arc */}
            <path
              d="M 100 20 A 60 60 0 0 1 100 140"
              stroke={primaryColor}
              strokeWidth="2"
              fill="none"
              strokeLinecap="round"
              opacity={entranceSpring}
              style={{
                transform: `translateX(-20px)`, // Center the arc relative to the ball
              }}
            />
          </svg>

          {/* The Ball (Robot Head) */}
          <div
            style={{
              width: 90,
              height: 90,
              borderRadius: "50%",
              backgroundColor: ballColor,
              position: "relative",
              zIndex: 10,
              transform: `scale(${entranceSpring}) rotate(${rotation}deg)`,
              boxShadow: "0 10px 25px rgba(0,0,0,0.1)",
              overflow: "hidden", // Masks the inner shapes to the circle
            }}
          >
            {/* Inner White Mouth/Face Area */}
            <div
              style={{
                position: "absolute",
                bottom: -10,
                left: "50%",
                width: 100,
                height: 60,
                backgroundColor: "white",
                borderRadius: "50%",
                transform: "translate(-50%, 0)",
              }}
            />

            {/* Eye / Highlight (Diamond shape) */}
            <div
              style={{
                position: "absolute",
                top: 20,
                left: 20,
                width: 12,
                height: 12,
                backgroundColor: "white",
                transform: "rotate(45deg)",
                borderRadius: 2,
              }}
            />
          </div>
        </div>

        {/* ------------------------------------------------------------------
            RIGHT SECTION: Scrolling Loaders List
        ------------------------------------------------------------------ */}
        <div
          style={{
            position: "relative",
            height: CONTAINER_HEIGHT, // Matches the center robot height
            minWidth: 400, // Prevent shifting
            overflow: "hidden", // Clips items exiting
          }}
        >
          {loaders.map((text, index) => {
            // Current raw Y position relative to container top
            // (index * ITEM_HEIGHT) stacks them downwards
            const initialItemY = START_Y_POS + (index * ITEM_HEIGHT);
            const currentY = initialItemY - currentScrollOffset;

            // Distance from visual center
            // Used to calculate blur and opacity relative to the "focal point"
            const distFromCenter = Math.abs(currentY - CENTER_Y);

            // Interpolate styles based on position
            // Center (0 dist) = Opacity 1, Blur 0
            // Edges (>100 dist) = Opacity 0, Blur High
            const opacity = interpolate(
              distFromCenter,
              [0, 80, 140],
              [1, 0.5, 0],
              { extrapolateRight: "clamp" }
            );

            const blurRadius = interpolate(
              distFromCenter,
              [0, 80, 140],
              [0, 2, 8],
              { extrapolateRight: "clamp" }
            );

            // Only render if roughly visible to save resources (optional optimization)
            if (currentY < -50 || currentY > CONTAINER_HEIGHT + 50) return null;

            return (
              <div
                key={index}
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: ITEM_HEIGHT,
                  display: "flex",
                  alignItems: "center", // Center text vertically in the row
                  fontSize: 32,
                  lineHeight: 1.4,
                  transform: `translateY(${currentY}px) translateY(-50%)`, // -50% to align center point
                  opacity,
                  filter: `blur(${blurRadius}px)`,
                  willChange: "transform, opacity, filter",
                }}
              >
                {renderColoredText(text)}
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default RobotLoader;